const raw = $input.first().json;
const item = raw && raw.body ? raw.body : raw;
const startedAt = new Date().toISOString();

if (!item.execution_id) throw new Error('Missing execution_id in payload');
if (!item.callback || !item.callback.url || !item.callback.secret) {
  throw new Error('Missing callback.url or callback.secret in payload');
}

const config = item.config || {};
const sheetId = (config.sheet_id || 'mock-sheet').toString();
const requiredColumnsRaw = (config.required_columns || 'name,email,phone').toString();
const requiredColumns = requiredColumnsRaw.split(',').map((s) => s.trim()).filter(Boolean);
const simulateFailure = config.simulate_failure === true;

const buildCallback = (status, result, error, metrics) => {
  const finishedAt = new Date().toISOString();
  return {
    callbackUrl: item.callback.url,
    callbackSecret: item.callback.secret,
    callbackBody: {
      execution_id: item.execution_id,
      agent_instance_id: item.agent_instance_id,
      template_id: item.template_id,
      status,
      n8n_execution_id: $execution.id,
      started_at: startedAt,
      finished_at: finishedAt,
      metrics,
      result,
      error
    },
    httpResponse: { received: true, execution_id: item.execution_id, status }
  };
};

if (simulateFailure) {
  return [{
    json: buildCallback(
      'failed',
      null,
      { code: 'MOCK_PROVIDER_TIMEOUT', message: 'Simulated provider timeout for demo', retryable: true },
      { input_count: 0, output_count: 0, error_count: 1, tokens_input: 0, tokens_output: 0, estimated_cost_usd: 0 }
    )
  }];
}

const FIRST_NAMES = ['Alex','Mira','Kai','Sam','Priya','Jordan','Chen','Ravi','Lin','Owen'];
const LAST_NAMES = ['Brooks','Patel','Nguyen','Carter','Singh','Park','Lopez','Khan','Reyes','Adams'];
const STATUSES = ['active','active','active','pending','inactive'];
const DOMAINS = ['acme.io','northwind.example','contoso.dev','globex.test'];

const PLANTED = {
  12: (r) => { r.email = ''; },
  23: (r) => { r.age = 150; },
  34: (r) => { r.name = ''; },
  45: (r) => { r.email = 'not-an-email'; },
  67: (r) => { r.phone = ''; },
  78: (r) => { r.age = -5; },
  89: (r) => { r.name = ''; }
};

const providedItems = item.input && Array.isArray(item.input.items) ? item.input.items : [];
let rows;
if (providedItems.length > 0) {
  rows = providedItems.map((r, idx) => ({
    id: r.id ?? idx + 1,
    name: r.name ?? '',
    email: r.email ?? '',
    phone: r.phone ?? '',
    age: typeof r.age === 'number' ? r.age : 0,
    status: r.status ?? 'active'
  }));
} else {
  rows = [];
  for (let i = 1; i <= 100; i++) {
    const first = FIRST_NAMES[i % FIRST_NAMES.length];
    const last = LAST_NAMES[(i * 3) % LAST_NAMES.length];
    const domain = DOMAINS[i % DOMAINS.length];
    const row = {
      id: i,
      name: first + ' ' + last,
      email: first.toLowerCase() + '.' + last.toLowerCase() + i + '@' + domain,
      phone: '+1-555-' + String(1000 + i).padStart(4, '0'),
      age: 20 + ((i * 7) % 50),
      status: STATUSES[i % STATUSES.length]
    };
    if (PLANTED[i]) PLANTED[i](row);
    rows.push(row);
  }
}

const isValidEmail = (e) => typeof e === 'string' && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);
const isMissing = (v) => v === undefined || v === null || v === '';

const issues = [];
for (const row of rows) {
  for (const col of requiredColumns) {
    if (isMissing(row[col])) {
      issues.push({ row: row.id, field: col, issue: 'missing ' + col });
    }
  }
  if (row.email && !isMissing(row.email) && !isValidEmail(row.email)) {
    issues.push({ row: row.id, field: 'email', issue: 'invalid email format' });
  }
  if (typeof row.age === 'number' && (row.age < 0 || row.age > 120)) {
    issues.push({ row: row.id, field: 'age', issue: 'age out of range: ' + row.age });
  }
}

const invalidRowIds = new Set(issues.map((x) => x.row));
const invalidRows = invalidRowIds.size;
const rowsChecked = rows.length;
const summary = rowsChecked + ' rows checked. ' + invalidRows + ' invalid row' + (invalidRows === 1 ? '' : 's') + ' found.';

return [{
  json: buildCallback(
    'success',
    {
      summary,
      data: {
        items_processed: rowsChecked,
        sheet_id: sheetId,
        rows_checked: rowsChecked,
        invalid_rows: invalidRows,
        issues,
        summary
      }
    },
    null,
    {
      input_count: rowsChecked,
      output_count: rowsChecked - invalidRows,
      error_count: invalidRows,
      tokens_input: 0,
      tokens_output: Math.ceil(JSON.stringify(issues).length / 4),
      estimated_cost_usd: Number((rowsChecked * 0.0001).toFixed(4))
    }
  )
}];
